  };
  state.handler = event => {
    if (event.key !== "F9" || event.repeat) return;
    state.running = !state.running;
    if (state.running) {
      state.timer = setInterval(() => {
        const target = document.elementFromPoint(state.x, state.y);
        if (target) target.click();
      }, 0);
    } else {
      clearInterval(state.timer);
    }
  };
  window.addEventListener("mousemove", state.move);
  window.addEventListener("keydown", state.handler);
  window[key] = state;
